1	const PROCESSING_FEE = 5;
2	
3	const BASE_PREMIUMS: Record<string, number> = {
4	  sword: 100,
5	  amulet: 60,
6	};
7	
8	const COMPONENT_BASE_PREMIUM = 25;
9	const COMPONENT_BLOCK_SIZE = 3;
10	const COMPONENT_BLOCK_PREMIUM = 60;
11	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
12	
13	const FIRST_INSURANCE_SURCHARGE = 0.1;
14	const CURSE_SURCHARGE = 0.5;
15	const HIGH_ENCHANTMENT_SURCHARGE = 0.3;
16	const HIGH_ENCHANTMENT_THRESHOLD = 5;
17	const LOYALTY_DISCOUNT = 0.2;
18	const LOYALTY_YEARS_THRESHOLD = 2;
19	const FOLLOWUP_CONTRACT_DISCOUNT = 0.15;
20	
21	const INSURANCE_VALUES: Record<string, number> = {
22	  sword: 1000,
23	};
24	
25	const DEDUCTIBLE = 100;
26	const CAP_MULTIPLIER = 2;
27	
28	interface Item {
29	  type: string;
30	  cursed?: boolean;
31	  enchantment?: number;
32	}
33	
34	interface QuoteStep {
35	  op: "quote";
36	  items: Item[];
37	}
38	
39	interface Damage {
40	  itemType: string;
41	  amount: number;
42	}
43	
44	interface ClaimStep {
45	  op: "claim";
46	  policy: number;
47	  incident: { cause: string; damages: Damage[] };
48	}
49	
50	type Step = QuoteStep | ClaimStep;
51	
52	interface Customer {
53	  yearsWithMHPCO: number;
54	}
55	
56	interface Scenario {
57	  customer: Customer;
58	  steps: Step[];
59	}
60	
61	interface QuoteResult {
62	  premium: number;
63	}
64	
65	interface ClaimResult {
66	  payout: number;
67	  remainingCap: number;
68	}
69	
70	type StepResult = QuoteResult | ClaimResult;
71	
72	interface ScenarioResult {
73	  results: StepResult[];
74	}
75	
76	const componentGroupBase = (count: number): number =>
77	  count === COMPONENT_BLOCK_SIZE
78	    ? COMPONENT_BLOCK_PREMIUM
79	    : count * COMPONENT_BASE_PREMIUM;
80	
81	const countByType = (items: Item[]): Map<string, number> => {
82	  const counts = new Map<string, number>();
83	  for (const item of items) {
84	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
85	  }
86	  return counts;
87	};
88	
89	const isComponent = (item: Item): boolean => COMPONENT_TYPES.has(item.type);
90	
91	const isHighEnchantment = (item: Item): boolean =>
92	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
93	
94	interface PricedUnit {
95	  base: number;
96	  surcharges: number[];
97	}
98	
99	const mainItemUnit = (item: Item): PricedUnit => {
100	  const base = BASE_PREMIUMS[item.type];
101	  const surcharges: number[] = [];
102	  if (item.cursed) surcharges.push(base * CURSE_SURCHARGE);
103	  if (isHighEnchantment(item)) surcharges.push(base * HIGH_ENCHANTMENT_SURCHARGE);
104	  return { base, surcharges };
105	};
106	
107	const componentUnit = (count: number): PricedUnit => ({
108	  base: componentGroupBase(count),
109	  surcharges: [],
110	});
111	
112	const pricedUnits = (items: Item[]): PricedUnit[] => {
113	  const mainUnits = items.filter((item) => !isComponent(item)).map(mainItemUnit);
114	
115	  const components = items.filter(isComponent);
116	  const componentUnits = [...countByType(components).values()].map(componentUnit);
117	
118	  return [...mainUnits, ...componentUnits];
119	};
120	
121	const unitTotal = (unit: PricedUnit): number =>
122	  unit.base +
123	  unit.base * FIRST_INSURANCE_SURCHARGE +
124	  unit.surcharges.reduce((sum, surcharge) => sum + surcharge, 0);
125	
126	// Policy-level discount fractions applied to the policy base (sum of unit bases).
127	// Each entry that applies contributes its fraction; new modifiers (e.g. follow-up
128	// contract discount) can be added here without touching per-item pricing.
129	const policyBaseDiscountFractions = (customer: Customer, isFollowUp: boolean): number[] => {
130	  const fractions: number[] = [];
131	  if (customer.yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD) fractions.push(LOYALTY_DISCOUNT);
132	  if (isFollowUp) fractions.push(FOLLOWUP_CONTRACT_DISCOUNT);
133	  return fractions;
134	};
135	
136	const quotePremium = (items: Item[], customer: Customer, isFollowUp: boolean): number => {
137	  const units = pricedUnits(items);
138	  const itemsTotal = units.reduce((sum, unit) => sum + unitTotal(unit), 0);
139	  const policyBase = units.reduce((sum, unit) => sum + unit.base, 0);
140	  const policyDiscount = policyBaseDiscountFractions(customer, isFollowUp).reduce(
141	    (sum, fraction) => sum + policyBase * fraction,
142	    0,
143	  );
144	  return Math.ceil(itemsTotal - policyDiscount + PROCESSING_FEE);
145	};
146	
147	interface Policy {
148	  items: Item[];
149	  cap: number;
150	}
151	
152	const createPolicy = (items: Item[]): Policy => {
153	  const insuranceSum = items.reduce((sum, item) => sum + INSURANCE_VALUES[item.type], 0);
154	  return { items, cap: insuranceSum * CAP_MULTIPLIER };
155	};
156	
157	const damagePayout = (damage: Damage): number => damage.amount - DEDUCTIBLE;
158	
159	const processClaim = (policy: Policy, damages: Damage[]): ClaimResult => {
160	  const payout = damages.reduce((sum, damage) => sum + damagePayout(damage), 0);
161	  return { payout, remainingCap: policy.cap - payout };
162	};
163	
164	export const runScenario = (scenario: Scenario): ScenarioResult => {
165	  const policies: Policy[] = [];
166	  let quoteCount = 0;
167	  const results = scenario.steps.map((step): StepResult => {
168	    if (step.op === "quote") {
169	      const isFollowUp = quoteCount > 0;
170	      quoteCount += 1;
171	      policies.push(createPolicy(step.items));
172	      return { premium: quotePremium(step.items, scenario.customer, isFollowUp) };
173	    }
174	    return processClaim(policies[step.policy], step.incident.damages);
175	  });
176	  return { results };
177	};
